41	@SpringBootTest
42	class AirspaceReviewServiceH2Test {
43	
44	    @Autowired
45	    private com.example.starter.service.AirspaceReviewService service;
46	    @Autowired
47	    private JdbcTemplate jdbc;
48	    @Autowired
49	    private ObjectMapper objectMapper;
50	
51	    private final AtomicInteger seq = new AtomicInteger();
52	
53	    @BeforeEach
54	    void cleanBefore() {
55	        cleanup();
56	    }
57	
58	    @AfterEach
59	    void cleanAfter() {
60	        cleanup();
61	    }
62	
63	    private void cleanup() {
64	        jdbc.update("DELETE FROM review");
65	        jdbc.update("DELETE FROM request_dedup");
66	        jdbc.update("DELETE FROM route_point");
67	        jdbc.update("DELETE FROM route");
68	        jdbc.update("DELETE FROM no_fly_zone");
69	        jdbc.update("UPDATE airspace_meta SET global_version = 0 WHERE id = 1");
70	    }
71	
72	    private String rid(String prefix) {
73	        return prefix + "-" + seq.incrementAndGet();
74	    }
75	
76	    private static List<RoutePointDto> pts(int... xy) {
77	        return java.util.stream.IntStream.range(0, xy.length / 2)
78	                .mapToObj(i -> new RoutePointDto(xy[2 * i], xy[2 * i + 1]))
79	                .toList();
80	    }
81	
82	    private ZoneCreateRequest zoneReq(String zoneId, int xMin, int yMin, int xMax, int yMax) {
83	        return new ZoneCreateRequest(zoneId, xMin, yMin, xMax, yMax, "req-" + rid("zone"));
84	    }
85	
86	    private ReviewResultDto dataOf(MutationResponse resp) {
87	        return objectMapper.convertValue(resp.data(), ReviewResultDto.class);
88	    }
89	
90	    // ============================ 主流程 ============================
91	
92	    @Test
93	    void clearThenBlockedThenClearAfterRevoke() {
94	        // 航线水平穿过 y=10
95	        MutationResponse route = service.createRoute(
96	                new RouteCreateRequest("r1", pts(0, 10, 100, 10), "req-" + rid("route")));
97	        assertFalse(route.replayed());
98	        assertEquals(1, objectMapper.convertValue(route.data(), Map.class).get("version"));
99	
100	        // 初始空域版本 0，无禁飞区 → CLEAR
101	        MutationResponse r1 = service.review(
102	                new ReviewRequest("r1", 1, 0L, "req-" + rid("review")));
103	        ReviewResultDto c1 = dataOf(r1);
104	        assertEquals("CLEAR", c1.conclusion());
105	        assertTrue(c1.hitZoneIds().isEmpty());
106	        assertEquals(0L, c1.airspaceVersion());
107	        assertTrue(c1.current());
108	
109	        // 创建与航线相交的禁飞区后，空域版本变为 1
110	        MutationResponse z1 = service.createZone(zoneReq("z1", 40, 5, 60, 15));
111	        assertEquals(1, ((Number) objectMapper.convertValue(z1.data(), Map.class)
112	                .get("airspaceVersion")).intValue());
113	
114	        // 用旧空域版本审核 → 409
115	        ApiException oldVersion = assertThrows(ApiException.class, () -> service.review(
116	                new ReviewRequest("r1", 1, 0L, "req-" + rid("review"))));
117	        assertEquals(HttpStatus.CONFLICT, oldVersion.status());
118	
119	        // 用新版本审核 → BLOCKED
120	        MutationResponse r2 = service.review(
121	                new ReviewRequest("r1", 1, 1L, "req-" + rid("review")));
122	        ReviewResultDto b1 = dataOf(r2);
123	        assertEquals("BLOCKED", b1.conclusion());
124	        assertEquals(List.of("z1"), b1.hitZoneIds());
125	
126	        // 撤销禁飞区，空域版本变为 2，再审核 → CLEAR
127	        service.revokeZone(new ZoneRevokeRequest("z1", "req-" + rid("revoke")));
128	        MutationResponse r3 = service.review(
129	                new ReviewRequest("r1", 1, 2L, "req-" + rid("review")));
130	        assertEquals("CLEAR", dataOf(r3).conclusion());
131	
132	        // 历史记录保留原结论
133	        assertEquals("BLOCKED", service.getReview(b1.reviewId()).conclusion());
134	        assertNull(service.getReview(b1.reviewId()).current());
135	    }
136	
137	    @Test
138	    void blockedReturnsAllHitZoneIdsSortedAndDeduplicated() {
139	        service.createRoute(
140	                new RouteCreateRequest("r2", pts(0, 10, 100, 10), "req-" + rid("route")));
141	        // 三个相交区域 + 一个不相交区域，id 故意乱序
142	        service.createZone(zoneReq("zeta", 40, 5, 60, 15));
