419	    @Test
420	    void concurrentZoneCreateAndReviewNeverMixesVersionsAndZones() throws Exception {
421	        int iterations = 12;
422	        ExecutorService pool = Executors.newFixedThreadPool(4);
423	        try {
424	            for (int i = 0; i < iterations; i++) {
425	                String routeId = "cr-" + i;
426	                String zoneId = "cz-" + i;
427	                // 每轮使用互不相交的 y 几何，避免历史轮次已提交区域命中本轮新航线
428	                int y = 10 + i * 100;
429	                service.createRoute(new RouteCreateRequest(
430	                        routeId, pts(0, y, 100, y), "req-" + rid("route")));
431	                long versionBefore = jdbc.queryForObject(
432	                        "SELECT global_version FROM airspace_meta WHERE id=1", Long.class);
433	
434	                CyclicBarrier barrier = new CyclicBarrier(2);
435	                // 审核方：明确提交建区前的空域版本
436	                Future<Object> reviewFuture = pool.submit(() -> {
437	                    barrier.await(5, TimeUnit.SECONDS);
438	                    try {
439	                        return service.review(new ReviewRequest(
440	                                routeId, 1, versionBefore, "req-review-" + routeId));
441	                    } catch (ApiException ex) {
442	                        return ex;
443	                    }
444	                });
445	                // 建区方：创建恰好封锁本轮航线的区域
446	                Future<Object> zoneFuture = pool.submit(() -> {
447	                    barrier.await(5, TimeUnit.SECONDS);
448	                    try {
449	                        return service.createZone(new ZoneCreateRequest(
450	                                zoneId, 40, y - 5, 60, y + 5, "req-zone-" + zoneId));
451	                    } catch (ApiException ex) {
452	                        return ex;
453	                    }
454	                });
455	
456	                Object reviewResult = reviewFuture.get(15, TimeUnit.SECONDS);
457	                Object zoneResult = zoneFuture.get(15, TimeUnit.SECONDS);
458	                assertTrue(zoneResult instanceof MutationResponse, "建区必须成功");
459	
460	                if (reviewResult instanceof MutationResponse mr) {
461	                    // 审核先拿锁：它看到的是建区前的一致快照，结论只能是 CLEAR，
462	                    // 绝不能出现“空域版本是旧的却命中新区域”的 BLOCKED
463	                    ReviewResultDto dto = dataOf(mr);
464	                    assertEquals("CLEAR", dto.conclusion(),
465	                            "并发审核携带旧空域版本时不得使用新建区域判定");
466	                    assertEquals(versionBefore, dto.airspaceVersion());
467	                } else {
468	                    // 建区先提交：版本已推进，审核必须 409，不能产生任何结论
469	                    ApiException ex = (ApiException) reviewResult;
470	                    assertEquals(HttpStatus.CONFLICT, ex.status());
471	                }
472	            }
473	        } finally {
474	            pool.shutdownNow();
475	        }
476	    }
