                new ReviewRequest("lk7", 2, 0L, "req-" + rid("review")));
        assertEquals("LINK_BLOCKED", dataOf(v2Review).conclusion());
        assertEquals("5100", dataOf(v2Review).linkGaps().get(0).lossMillis());
